import zipfile, re
z = zipfile.ZipFile('/root/safety_audit_brief_final.hwpx')
for name in z.namelist():
    if name.endswith('.xml'):
        data = z.read(name).decode('utf-8')
        phs = re.findall(r'\{\{[^}]+\}\}', data)
        if phs:
            print(f'FAIL: {name} has placeholders: {phs}')
        if 'lineSegArray' in data or 'linesegarray' in data.lower():
            count = data.lower().count('linesegarray')
            print(f'WARN: {name} still has {count} linesegarray occurrences')
print('Validation complete')
